import React from "react";
import { useNavigate } from "react-router-dom";
import { Code2, Database, Cpu, Braces, Palette } from "lucide-react";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">

      <div className="container">

        {/* LEFT SIDE */}
        <div className="left">

          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Builder • UI Thinker
          </h2>

          <p className="desc">
            I design structured systems and build meaningful applications
            where logic, design, and performance work together.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>
            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>

        </div>

        {/* RIGHT RADAR */}
        <div className="right">

          <div className="radar">

            {/* RINGS */}
            <div className="ring r1"></div>
            <div className="ring r2"></div>
            <div className="ring r3"></div>

            {/* 🌙 SCANNING SEMI LIGHT */}
            <div className="sweep"></div>

            {/* CENTER IMAGE ONLY (NO TEXT) */}
            <div className="center">
              <img
                src="https://i.ibb.co/4f1R9Zc/female-avatar.png"
                alt="avatar"
              />
            </div>

            {/* ICONS ONLY */}
            <div className="icon i1"><Code2 size={18} /></div>
            <div className="icon i2"><Database size={18} /></div>
            <div className="icon i3"><Cpu size={18} /></div>
            <div className="icon i4"><Braces size={18} /></div>
            <div className="icon i5"><Palette size={18} /></div>

            {/* 🌟 RING PARTICLES */}
            <span className="dot d1"></span>
            <span className="dot d2"></span>
            <span className="dot d3"></span>
            <span className="dot d4"></span>
            <span className="dot d5"></span>

          </div>

        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 8%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 60px;
          width: 100%;
          align-items: center;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
        }

        h1 {
          font-size: 62px;
        }

        .name {
          color: #38BDF8;
        }

        .role {
          font-size: 20px;
          color: #94a3b8;
        }

        .desc {
          margin-top: 18px;
          font-size: 16px;
          color: #cbd5e1;
          line-height: 1.7;
          max-width: 520px;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          font-weight: 600;
          border: 1px solid rgba(56,189,248,0.3);
        }

        .primary {
          background: #38BDF8;
          color: #0b1220;
        }

        .secondary {
          background: rgba(255,255,255,0.03);
          color: #38BDF8;
        }

        /* =========================
           RADAR SYSTEM
        ========================== */

        .radar {
          position: relative;
          width: 380px;
          height: 380px;
          margin: auto;
        }

        /* RINGS */
        .ring {
          position: absolute;
          border-radius: 50%;
          border: 1px solid rgba(56,189,248,0.12);
        }

        .r1 {
          width: 360px;
          height: 360px;
          top: 10px;
          left: 10px;
        }

        .r2 {
          width: 260px;
          height: 260px;
          top: 60px;
          left: 60px;
        }

        .r3 {
          width: 160px;
          height: 160px;
          top: 110px;
          left: 110px;
        }

        /* 🌙 SEMI RADAR SWEEP */
        .sweep {
          position: absolute;
          width: 180px;
          height: 180px;
          top: 100px;
          left: 100px;

          border-radius: 50%;
          background: conic-gradient(
            from 90deg,
            transparent,
            rgba(56,189,248,0.2),
            transparent
          );

          animation: rotateSweep 4s linear infinite;
          filter: blur(2px);
        }

        @keyframes rotateSweep {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }

        /* CENTER */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%,-50%);
          z-index: 5;
        }

        .center img {
          width: 110px;
          height: 110px;
          border-radius: 50%;
          border: 2px solid rgba(56,189,248,0.5);
          box-shadow: 0 0 25px rgba(56,189,248,0.25);
        }

        /* ICONS (NO TEXT LABELS) */
        .icon {
          position: absolute;
          width: 34px;
          height: 34px;

          display: flex;
          align-items: center;
          justify-content: center;

          border-radius: 50%;
          background: rgba(255,255,255,0.05);
          border: 1px solid rgba(56,189,248,0.2);
          color: #38BDF8;

          box-shadow: 0 0 10px rgba(56,189,248,0.15);
        }

        .i1 { top: 0; left: 50%; transform: translateX(-50%); }
        .i2 { top: 30%; right: 0; }
        .i3 { bottom: 0; left: 50%; transform: translateX(-50%); }
        .i4 { top: 50%; left: 0; transform: translateY(-50%); }
        .i5 { top: 15%; right: 20%; }

        /* 🌟 PARTICLES ON RINGS */
        .dot {
          position: absolute;
          width: 5px;
          height: 5px;
          background: #38BDF8;
          border-radius: 50%;
          box-shadow: 0 0 10px #38BDF8;
        }

        .d1 { top: 40px; left: 120px; }
        .d2 { top: 200px; right: 40px; }
        .d3 { bottom: 80px; left: 60px; }
        .d4 { top: 150px; left: 180px; }
        .d5 { bottom: 40px; right: 120px; }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .container {
            grid-template-columns: 1fr;
            text-align: center;
          }

          h1 {
            font-size: 42px;
          }

          .buttons {
            justify-content: center;
          }

          .radar {
            margin-top: 40px;
          }
        }

      `}</style>

    </section>
  );
};

export default Hero;
